package com.qpwflshclub.formal_club.workspace;
import com.qpwflshclub.formal_club.social.*;import com.qpwflshclub.formal_club.repository.Club.ClubRepository;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.core.io.*;import jakarta.servlet.http.HttpServletRequest;import java.nio.file.*;import java.util.*;import java.io.*;
@RestController public class ClubMediaController {
 private final WorkspaceAccess access;private final ClubRepository clubs;private final WallFiles images;private final Path root;
 public ClubMediaController(WorkspaceAccess a,ClubRepository c,WallFiles images,@Value("${club.media-dir:./data/club-media}")String root){access=a;clubs=c;this.images=images;this.root=Path.of(root);}
 @PostMapping("/api/club-workspace/{club}/media/{kind}") public Object upload(@PathVariable int club,@PathVariable String kind,@RequestParam MultipartFile file,HttpServletRequest request)throws IOException{var c=access.require(access.current(request),club);access.mutation(request);if(file.isEmpty()||file.getSize()>40L*1024*1024)throw SchoolAccounts.error(400,"文件不能超过 40 MB / Files must be under 40 MB");Files.createDirectories(root);String name=UUID.randomUUID()+ (kind.equals("logo")?".jpg":".mp4");Path target=root.resolve(name);if(kind.equals("logo")){var saved=images.save(file,false);try{if(!saved.type().startsWith("image/"))throw SchoolAccounts.error(400,"Logo 请使用 JPG 或 PNG / Use JPG or PNG");Files.write(target,images.read(saved.id()));}finally{images.remove(saved.id());}}else if(kind.equals("video")){try(var input=file.getInputStream()){byte[] h=input.readNBytes(12);if(h.length<12||!new String(h,4,4,java.nio.charset.StandardCharsets.US_ASCII).equals("ftyp"))throw SchoolAccounts.error(400,"请选择 MP4 视频 / Select an MP4 video");}Path input=Files.createTempFile("club-video-",".mp4");try{file.transferTo(input);MediaCompression.video(input,target);}finally{Files.deleteIfExists(input);}}else throw SchoolAccounts.error(400,"Unsupported media");String url="/club-media/"+name;try{if(kind.equals("logo"))c.setClubItem(url);else c.setVideo(url);clubs.save(c);}catch(RuntimeException e){Files.deleteIfExists(target);throw e;}return Map.of("url",url);}
 @GetMapping("/club-media/{name}") public ResponseEntity<Resource> read(@PathVariable String name){if(!name.matches("[a-f0-9-]{36}\\.(png|jpg|mp4)"))throw SchoolAccounts.error(404,"Not found");Path p=root.resolve(name);if(!Files.isRegularFile(p))throw SchoolAccounts.error(404,"Not found");return ResponseEntity.ok().contentType(MediaType.parseMediaType(name.endsWith(".png")?"image/png":name.endsWith(".jpg")?"image/jpeg":"video/mp4")).header("X-Content-Type-Options","nosniff").body(new FileSystemResource(p));}
}
